        for (Car car : cars) {
            String color = car.getColor();
            colorCounts.put(color, colorCounts.getOrDefault(color, 0) + 1);
        }

        String mostPopularColor = Collections.max(colorCounts.entrySet(), Comparator.comparingInt(Map.Entry::getValue)).getKey();
        int mostPopularCount = colorCounts.get(mostPopularColor);

        return new CarColorStats(mostPopularColor, mostPopularCount);
    }

    public static void main(String[] args) {
        List<Car> cars = Arrays.asList(
            new Car("Red"),
            new Car("Blue"),
            new Car("Red"),
            new Car("Green"),
            new Car("Blue"),
            new Car("Red")
        );

        CarColorStats stats = mostPopularCarColor(cars);
        System.out.println("Most popular car color: " + stats.getColor());
        System.out.println("Count: " + stats.getCount());
    }
}
